  // Calculate duration in hours
  const durationMs = endTime - startTime;
  const durationHours = durationMs / (1000 * 60 * 60); // Convert ms to hours

  return {
    json: {
      ...shift.json,
      durationHours: parseFloat(durationHours.toFixed(2)),
