      endTimeFormatted: endTime.toLocaleString()
    }
  };
});"},"typeVersion":2},{"id":"2056749a-1d0c-4e0b-bf32-110110111117","name":"Calculate Employee Metrics","type":"n8n-nodes-base.code","position":[1232,16],"parameters":{"jsCode":"// Input: Array of employee shift records
const shifts = $input.all();

// Group shifts by employee ID
const employeeData = {};

shifts.forEach(shift => {
  const empId = shift.json.employeeId;

  if (!employeeData[empId]) {
    employeeData[empId] = {
      employeeId: empId,
      employeeName: shift.json.employeeName || 'Unknown',
      totalShifts: 0,
      totalHours: 0,
      totalSales: 0,
      totalTips: 0,
      shifts: []
    };
  }

  employeeData[empId].totalShifts++;
  employeeData[empId].totalHours += parseFloat(shift.json.durationHours || 0);
  employeeData[empId].totalSales += parseFloat(shift.json.salesAmount || 0);
  employeeData[empId].totalTips += parseFloat(shift.json.tips || 0);
  employeeData[empId].shifts.push({
    date: shift.json.date,
    startTime: shift.json.startTimeFormatted,
    endTime: shift.json.endTimeFormatted,
    duration: shift.json.durationHours,
    sales: shift.json.salesAmount,
    tips: shift.json.tips
  });
});

// Calculate averages and convert to array
const results = Object.values(employeeData).map(emp => ({
  json: {
    ...emp,
    averageHoursPerShift: parseFloat((emp.totalHours / Math.max(emp.totalShifts, 1)).toFixed(2)),
    averageSalesPerShift: parseFloat((emp.totalSales / Math.max(emp.totalShifts, 1)).toFixed(2)),
    averageTipsPerShift: parseFloat((emp.totalTips / Math.max(emp.totalShifts, 1)).toFixed(2)),
    hourlyRate: parseFloat((emp.totalSales / Math.max(emp.totalHours, 0.01)).toFixed(2))
  }
}));

return results;"},"typeVersion":2},{"id":"2056749a-1d0c-4e0b-bf32-110110111118","name":"Aggregate Daily Metrics","type":"n8n-nodes-base.code","position":[1456,16],"parameters":{"jsCode":"// Input: Array of daily transaction records
const transactions = $input.all();

// Group transactions by date
const dailyData = {};

transactions.forEach(transaction => {
  const date = transaction.json.date || transaction.json.timestamp.split('T')[0];

  if (!dailyData[date]) {
    dailyData[date] = {
      date: date,
      totalRevenue: 0,
      totalOrders: 0,
      totalItemsSold: 0,
      totalDiscounts: 0,
      totalRefunds: 0,
      paymentMethods: {},
      topProducts: [],
      hourlyBreakdown: {}
    };
  }

  // Aggregate revenue
  dailyData[date].totalRevenue += parseFloat(transaction.json.amount || 0);
  dailyData[date].totalOrders++;
  dailyData[date].totalItemsSold += parseInt(transaction.json.quantity || 1);
  dailyData[date].totalDiscounts += parseFloat(transaction.json.discount || 0);
  dailyData[date].totalRefunds += parseFloat(transaction.json.refund || 0);

  // Payment methods breakdown
  const paymentMethod = transaction.json.paymentMethod || 'Cash';
  if (!dailyData[date].paymentMethods[paymentMethod]) {
    dailyData[date].paymentMethods[paymentMethod] = 0;
  }
  dailyData[date].paymentMethods[paymentMethod] += parseFloat(transaction.json.amount || 0);

  // Hourly breakdown
  const hour = transaction.json.timestamp ? new Date(transaction.json.timestamp).getHours() : 0;
  if (!dailyData[date].hourlyBreakdown[hour]) {
    dailyData[date].hourlyBreakdown[hour] = { revenue: 0, orders: 0 };
  }
  dailyData[date].hourlyBreakdown[hour].revenue += parseFloat(transaction.json.amount || 0);
  dailyData[date].hourlyBreakdown[hour].orders++;
});

// Calculate derived metrics for each day
const results = Object.values(dailyData).map(day => {
  const netRevenue = day.totalRevenue - day.totalDiscounts - day.totalRefunds;
  const avgOrderValue = day.totalOrders > 0 ? netRevenue / day.totalOrders : 0;

  // Find top payment method
  const topPaymentMethod = Object.entries(day.paymentMethods)
    .sort((a, b) => b[1] - a[1])[0];

  return {
    json: {
      ...day,
      netRevenue: parseFloat(netRevenue.toFixed(2)),
      averageOrderValue: parseFloat(avgOrderValue.toFixed(2)),
      topPaymentMethod: topPaymentMethod ? topPaymentMethod[0] : 'N/A',
      topPaymentMethodAmount: topPaymentMethod ? parseFloat(topPaymentMethod[1].toFixed(2)) : 0,
      refundRate: day.totalOrders > 0 ? parseFloat(((day.totalRefunds / day.totalRevenue) * 100).toFixed(2)) : 0
    }
  };
});

return results;"},"typeVersion":2},{"id":"2056749a-1d0c-4e0b-bf32-110110111119","name":"Append Daily Summary","type":"n8n-nodes-base.googleSheets","position":[1680,16],"parameters":{"columns":{"value":{},"schema":[],"mappingMode":"autoMapInputData","matchingColumns":[],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{},"operation":"append","sheetName":{"__rl":true,"mode":"list","value":"gid=0","cachedResultUrl":"https://docs.google.com/spreadsheets/d/1jgQJzYtXlqGvZxhBwKpLmNqRsTuVwXyZ0123456789A/edit#gid=0","cachedResultName":"Sheet1"},"documentId":{"__rl":true,"mode":"list","value":"1jgQJzYtXlqGvZxhBwKpLmNqRsTuVwXyZ0123456789A","cachedResultUrl":"https://docs.google.com/spreadsheets/d/1jgQJzYtXlqGvZxhBwKpLmNqRsTuVwXyZ0123456789A/edit?usp=drivesdk","cachedResultName":"Loyverse POS Data"}},"credentials":{"googleSheetsOAuth2Api":{"id":"credential-id","name":"googleSheetsOAuth2Api Credential"}},"typeVersion":4.5},{"id":"2056749a-1d0c-4e0b-bf32-110110111120","name":"Send Daily Report","type":"n8n-nodes-base.emailSend","position":[1904,16],"webhookId":"8a7b6c5d-4e3f-2a1b-0c9d-8e7f6a5b4c3d","parameters":{"html":"<!DOCTYPE html>
