Respond in JSON format. Make insights actionable and specific."},"promptType":"define","hasOutputParser":true},"typeVersion":3},{"id":"043da99d-83ad-47d7-bc63-d52b40adee67","name":"OpenAI Chat Model (Weekly)","type":"@n8n/n8n-nodes-langchain.lmChatOpenAi","position":[336,912],"parameters":{"model":{"__rl":true,"mode":"id","value":"gpt-4o"},"options":{},"builtInTools":{}},"typeVersion":1.3},{"id":"b9d7838d-9e4a-4991-9b6e-057e3212b48e","name":"Structured Output Parser (Weekly)","type":"@n8n/n8n-nodes-langchain.outputParserStructured","position":[480,912],"parameters":{"schemaType":"manual","inputSchema":"{
