const NewTime = new Date(testDate.toLocaleString('en-US', { timeZone: timezoneInput }));
const utcTime = new Date(testDate.toLocaleString('en-US', { timeZone: 'UTC' }));
const offsetHours = (NewTime - utcTime) / (1000 * 60 * 60);
const offsetStr = `+${Math.abs(offsetHours).toString().padStart(2, '0')}:00`;

// Convert pickup time from Kyiv to UTC
const pickUpTimeUTC = new Date(req.pickUpTime + offsetStr).toISOString();

