    orderId: orderId,
    name: req.name,
    phone: req.phone,
    items: req.items,
    pickUpTime: pickUpTimeUTC,
    priceTotal: req.priceTotal,
    notes: req.notes
  }
}];"},"typeVersion":2},{"id":"4e31b507-8d4d-4a85-935f-f12e40ffc233","name":"Replace with SMS node1","type":"n8n-nodes-base.noOp","position":[1328,784],"parameters":{},"typeVersion":1},{"id":"0d9fa7e5-82cb-4b46-ac1f-93666e2dc7b1","name":"Set Timezone3","type":"n8n-nodes-base.set","position":[656,784],"parameters":{"options":{},"assignments":{"assignments":[{"id":"edede7b3-cf44-4169-bb7c-81612f1cebfe","name":"timezone","type":"string","value":"Europe/Kyiv"}]}},"typeVersion":3.4},{"id":"56534c8b-8642-4428-9511-da831ccf881a","name":"Trigger Node5","type":"n8n-nodes-base.set","position":[448,784],"parameters":{"options":{},"assignments":{"assignments":[{"id":"32a318db-0d22-46d2-8156-a98a62e4b8ce","name":"name","type":"string","value":"string"},{"id":"d2236a00-a8c0-4915-8522-873c6e025fc1","name":"phone","type":"string","value":"string"},{"id":"57d0ec72-f5c1-40cd-bc08-7b3f85ba68eb","name":"items","type":"array","value":"string"},{"id":"f1bf4bbe-2469-426a-820f-c4f93e996a03","name":"pickUpTime","type":"string","value":"string"},{"id":"c0ca7e39-40f4-48c5-952c-710d694fd64b","name":"priceTotal","type":"string","value":"string"},{"id":"73103ffd-3717-45e9-b379-982bd00a1592","name":"notes","type":"string","value":"string"}]}},"typeVersion":3.4},{"id":"be0bdb1c-3c96-4ef7-88f0-b9cf2718b858","name":"Fetch Menu","type":"n8n-nodes-base.airtable","position":[1616,-336],"parameters":{"base":{"__rl":true,"mode":"list","value":"appO25aREhJMGVavR","cachedResultUrl":"https://airtable.com/appO25aREhJMGVavR","cachedResultName":"Restaurant Booking"},"table":{"__rl":true,"mode":"list","value":"tbl64YINWNUXFysQ7","cachedResultUrl":"https://airtable.com/appO25aREhJMGVavR/tbl64YINWNUXFysQ7","cachedResultName":"Menu"},"options":{},"operation":"search","filterByFormula":"{Available}"},"credentials":{"airtableTokenApi":{"id":"credential-id","name":"airtableTokenApi Credential"}},"typeVersion":2.1},{"id":"86c4bd86-d723-4b62-958f-8e0c4813c0a5","name":"Total Price","type":"n8n-nodes-base.set","position":[2288,-336],"parameters":{"options":{},"assignments":{"assignments":[{"id":"9a497db3-980a-4105-bf03-1909e7d0b41d","name":"Message","type":"string","value":"=Total price is {{ $json.total }}$."}]}},"typeVersion":3.4},{"id":"430ca7ec-c8ce-4e49-aea1-e26faca893ba","name":"Order Validation","type":"n8n-nodes-base.code","position":[1840,-336],"parameters":{"jsCode":"// Inputs
const order = $('When Executed by Another Workflow').first().json.items;
const menu = $('Fetch Menu').all().map(i => i.json);

// Validation
if (!Array.isArray(order)) {
  return [{ json: { status: false, error: "Order must be an items array" } }];
}

let total = 0;
const breakdown = [];

for (const item of order) {
  if (!item.name || !item.quantity) {
    return [{ json: { status: false, error: "Each order item must have name and quantity" } }];
  }

  const menuItem = menu.find(
    m => m["Item Name"]?.toLowerCase().trim() === item.name.toLowerCase().trim()
  );

  if (!menuItem) {
    return [{ json: { status: false, error: `Item not found in menu: ${item.name}` } }];
  }

  if (menuItem.Available !== true) {
    return [{ json: { status: false, error: `Item not available: ${menuItem["Item Name"]}` } }];
  }

  if (typeof menuItem.Price !== "number") {
    return [{ json: { status: false, error: `Invalid price for item: ${menuItem["Item Name"]}` } }];
  }

  const lineTotal = menuItem.Price * item.quantity;
  total += lineTotal;

  breakdown.push({
    name: menuItem["Item Name"],
    quantity: item.quantity,
    unitPrice: menuItem.Price,
    lineTotal
  });
}

return [{
  json: {
    status: true,
    total,
    items: breakdown
