const config = $('CONFIG - User Settings').item.json;
const timeZone = config.timezone || 'Asia/Ho_Chi_Minh';
const defaultCurrency = config.currency_code || 'USD';

function formatDateTimeInTZ(dateInput, tz) {
  const d = dateInput ? new Date(dateInput) : new Date();
  if (Number.isNaN(d.getTime())) return '';

  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false,
  }).formatToParts(d);

  const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day} ${map.hour}:${map.minute}:${map.second}`;
}

const expenses = $json.expenses ?? [];
const updateId = $node["Telegram Trigger"].json.update_id;
const fallbackDate = formatDateTimeInTZ($json.now ?? new Date(), timeZone);

return expenses.map((e) => {
  const dateValue = (typeof e?.date === 'string' && e.date.trim())
      ? e.date.trim()
      : fallbackDate;

  return {
    json: {
      update_id: updateId,
      message_id: $json.message_id,
      chat_id: $json.chat_id,
      source_type: $json.source_type,
      raw_input: $json.raw_input,

      item: e.item ?? '',
      amount: Number(e.amount ?? 0),
      // Use the default currency from the Config if the AI doesn't return it.
      currency: e.currency ?? defaultCurrency,
      category: e.category ?? 'Other',
      payment_method: e.payment_method ?? 'Cash',

      date: dateValue,
      summary_text: $json.summary_text,
    }
  };
});"},"typeVersion":2},{"id":"1cd58e0a-904a-4ac6-88dc-e35b6f3cbfc2","name":"Google Sheets → Append row(s)","type":"n8n-nodes-base.googleSheets","position":[3072,-80],"parameters":{"columns":{"value":{"Date":"={{ $json.date }}","Item":"={{ $json.item }}","Amount":"={{ $json.amount }}","Category":"={{ $json.category }}","Currency":"={{ $json.currency }}","Raw_Input":"={{ $json.raw_input }}","Update_ID":"={{ $json.update_id }}","Message_ID":"={{ $json.message_id }}","Payment_Method":"={{ $json.payment_method }}"},"schema":[{"id":"Update_ID","type":"string","display":true,"removed":false,"required":false,"displayName":"Update_ID","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Message_ID","type":"string","display":true,"required":false,"displayName":"Message_ID","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Date","type":"string","display":true,"required":false,"displayName":"Date","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Item","type":"string","display":true,"required":false,"displayName":"Item","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Amount","type":"string","display":true,"required":false,"displayName":"Amount","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Payment_Method","type":"string","display":true,"required":false,"displayName":"Payment_Method","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Category","type":"string","display":true,"required":false,"displayName":"Category","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Currency","type":"string","display":true,"required":false,"displayName":"Currency","defaultMatch":false,"canBeUsedToMatch":true},{"id":"Raw_Input","type":"string","display":true,"required":false,"displayName":"Raw_Input","defaultMatch":false,"canBeUsedToMatch":true}],"mappingMode":"defineBelow","matchingColumns":[],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{},"operation":"append","sheetName":{"__rl":true,"mode":"id","value":"={{ $('CONFIG - User Settings').item.json.s