const keyword = $input.first().json.Keyword
const location =  $input.first().json.Location
const experienceLevel = $input.first().json['Experience Level']
const remote = $input.first().json.Remote
const jobType = $input.first().json['Job Type']
const easyApply = $input.first().json['Easy Apply']

if (keyword != "") {
  url += `&keywords=${keyword}`;
}

if (location != "") {
  url += `&location=${location}`;
}

if (experienceLevel !== "") {
  // we have experienceLevel as a string with values like "Internship, Entry level"
  // we  transform it to "1,2,3" where:
  // Internship -> 1
  // Entry level -> 2
  // Associate -> 3
  // Mid-Senior level -> 4
  // Director -> 5
  // Executive -> 6
  const transformedExperiences = experienceLevel
    .split(",")
    .map((exp) => {
      switch (exp.trim()) {
        case "Internship":
          return "1";
        case "Entry level":
          return "2";
        case "Associate":
          return "3";
        case "Mid-Senior level":
          return "4";
        case "Director":
          return "5";
        case "Executive":
          return "6";
        default:
          return "";
      }
    })
    .filter(Boolean); // filter out any empty strings
  url += `&f_E=${transformedExperiences.join(",")}`;
}

if (remote.length != "") {
  // we have remote as a string with values like "Remote, Hybrid"
  // we transform it to "2,3,1" where:
  // On-Site -> 1
  // Remote -> 2
  // Hybrid -> 3
  const transformedRemote = remote
    .split(",")
    .map((e) => {
      switch (e.trim()) {
        case "Remote":
          return "2";
        case "Hybrid":
          return "3";
        case "On-Site":
          return "1";
        default:
          return "";
      }
    })
    .filter(Boolean); // filter out any empty strings
  url += `&f_WT=${transformedRemote.join(",")}`;
}

if (jobType != "") {
  // we have jobType as a string with values like "Full-time, Part-time"
  // we transform it to "F,P" where:
  // Full-time -> F
  // Part-time -> P
  // Contract -> C
  // Temporary -> T
  // Other -> O
  // Internship -> I
  const transformedJobType = jobType.split(",").map((type) => type.trim().charAt(0).toUpperCase());
  url += `&f_JT=${transformedJobType.join(",")}`;
}

if (easyApply != "") {
  url += "&f_EA=true";
}

return {url}"},"typeVersion":2},{"id":"a1261369-4939-44a5-908f-1f79cf05d275","name":"Schedule Trigger","type":"n8n-nodes-base.scheduleTrigger","position":[-240,-580],"parameters":{"rule":{"interval":[{"triggerAtHour":17}]}},"notesInFlow":false,"typeVersion":1.2},{"id":"13197864-2918-4e55-8991-8861ad723455","name":"Fetch Jobs from Linkedin","type":"n8n-nodes-base.httpRequest","position":[1220,-580],"parameters":{"url":"={{ $json.url }}","options":{}},"typeVersion":4.2},{"id":"df5815da-e55c-494e-919c-07b93ec4b9fa","name":"Fetch Job Page","type":"n8n-nodes-base.httpRequest","onError":"continueRegularOutput","position":[180,-260],"parameters":{"url":"={{ $json.links }}","options":{}},"executeOnce":false,"retryOnFail":true,"typeVersion":4.2,"waitBetweenTries":5000},{"id":"9838b440-d3ad-4665-b47b-d04e4d2cb928","name":"Parse AI Output","type":"n8n-nodes-base.set","position":[1360,-260],"parameters":{"mode":"raw","options":{},"jsonOutput":"={{ $json.output.replaceAll(/```(?:json)?/g, "") }}
